-- ---------- Complaints (mixed SLA states) -------------------------------
-- Category is auto-seeded per property by fn_property_seed_categories.
-- Fetch one for property A1 & A2.
DO $seed$
DECLARE cat_a1 uuid; cat_a2 uuid;
BEGIN
  SELECT id INTO cat_a1 FROM public.complaint_categories WHERE property_id='11111111-1111-1111-1111-11111111a001' ORDER BY display_order LIMIT 1;
  SELECT id INTO cat_a2 FROM public.complaint_categories WHERE property_id='11111111-1111-1111-1111-11111111a002' ORDER BY display_order LIMIT 1;

  -- OPEN, within SLA
  INSERT INTO public.complaints (id, tenant_id, property_id, block_id, student_id, category_id, complaint_number, title, description, status, sla_due_at)
  VALUES ('11111111-1111-1111-1111-11111111ca01','11111111-1111-1111-1111-111111111111','11111111-1111-1111-1111-11111111a001','11111111-1111-1111-1111-11111111b001','11111111-1111-1111-1111-111111110001', cat_a1, 'C-SEED-0001','Fan not working','Ceiling fan stuck','OPEN', now()+interval '2 hours');

  -- IN_PROGRESS assigned to warden A blockA
  INSERT INTO public.complaints (id, tenant_id, property_id, block_id, student_id, category_id, complaint_number, title, description, status, assigned_to, assigned_at, sla_due_at)
  VALUES ('11111111-1111-1111-1111-11111111ca02','11111111-1111-1111-1111-111111111111','11111111-1111-1111-1111-11111111a001','11111111-1111-1111-1111-11111111b001','11111111-1111-1111-1111-111111110002', cat_a1, 'C-SEED-0002','Water leak','Bathroom leak','IN_PROGRESS','00000000-0000-0000-0000-000000000011', now()-interval '1 hour', now()+interval '3 hours');

  -- SLA BREACHED (past due, not resolved)
  INSERT INTO public.complaints (id, tenant_id, property_id, block_id, student_id, category_id, complaint_number, title, description, status, assigned_to, assigned_at, sla_due_at, sla_breached_at)
  VALUES ('11111111-1111-1111-1111-11111111ca03','11111111-1111-1111-1111-111111111111','11111111-1111-1111-1111-11111111a001','11111111-1111-1111-1111-11111111b002','11111111-1111-1111-1111-111111110007', cat_a1, 'C-SEED-0003','No hot water','Geyser dead 3 days','OPEN','00000000-0000-0000-0000-000000000012', now()-interval '2 days', now()-interval '1 day', now()-interval '1 day');

  -- Property A2 open (no block)
  INSERT INTO public.complaints (id, tenant_id, property_id, student_id, category_id, complaint_number, title, description, status, sla_due_at)
  VALUES ('11111111-1111-1111-1111-11111111ca04','11111111-1111-1111-1111-111111111111','11111111-1111-1111-1111-11111111a002','11111111-1111-1111-1111-111111110009', cat_a2, 'C-SEED-0004','Wifi slow','Very slow speed','OPEN', now()+interval '6 hours');

  -- RESOLVED (within reopen window)
  INSERT INTO public.complaints (id, tenant_id, property_id, block_id, student_id, category_id, complaint_number, title, description, status, assigned_to, resolved_at, reopen_until, sla_due_at, resolution_summary, rating)
  VALUES ('11111111-1111-1111-1111-11111111ca05','11111111-1111-1111-1111-111111111111','11111111-1111-1111-1111-11111111a001','11111111-1111-1111-1111-11111111b001','11111111-1111-1111-1111-111111110003', cat_a1, 'C-SEED-0005','Bulb replaced','Fixed same day','RESOLVED','00000000-0000-0000-0000-000000000011', now()-interval '4 hours', now()+interval '44 hours', now()+interval '2 hours', 'Replaced LED bulb', 5);
END $seed$;

