-- ---------- Attendance (last 3 days for active students) ----------------
INSERT INTO public.attendance (tenant_id, property_id, block_id, student_id, attendance_date, session, status, marked_by, source)
SELECT '11111111-1111-1111-1111-111111111111', s.property_id, s.block_id, s.student_id, d, 'DAILY',
       CASE WHEN random() < 0.85 THEN 'PRESENT' ELSE 'ABSENT' END,
       '00000000-0000-0000-0000-000000000011', 'BULK'
FROM (
  SELECT a.student_id, a.property_id, a.block_id
  FROM public.allocations a
  WHERE a.status = 'ACTIVE'
) s
CROSS JOIN generate_series(current_date - 2, current_date, interval '1 day') d;

COMMIT;

-- Sanity summary
SELECT 'seed.complete' AS marker,
  (SELECT count(*) FROM public.tenants) AS tenants,
  (SELECT count(*) FROM public.properties) AS properties,
  (SELECT count(*) FROM public.students) AS students,
  (SELECT count(*) FROM public.allocations) AS allocations,
  (SELECT count(*) FROM public.invoices) AS invoices,
  (SELECT count(*) FROM public.complaints) AS complaints,
  (SELECT count(*) FROM public.gate_passes) AS gate_passes,
  (SELECT count(*) FROM public.attendance) AS attendance;
